import XCTest
@testable import MyFitPlateCore

/// Reduced public responses captured November 4, 2026. USDA: public-domain/CC0.
/// Open Food Facts: ODbL (https://opendatacommons.org/licenses/odbl/1-0/).
/// Projections preserve reported values; no personal food records are included.
final class FoodSearchCapturedResponseTests: XCTestCase {
    func testTypedBrandCannotBeRankedWhenBroadProviderWindowOmitsIt() throws {
        let broad = try USDAFoodParser.foodItems(from: Data(broadMilk.utf8))
        let specific = try USDAFoodParser.foodItems(from: Data(allWordsMilk.utf8))
        XCTAssertEqual(broad.count, 20)
        XCTAssertFalse(broad.contains { $0.name.lowercased().contains("fairlife") })
        let ranked = FoodSearchRanking.rankedRemoteMatches(query: "Fairlife 2% milk", foods: specific)
        XCTAssertEqual(ranked.count, 3)
        XCTAssertTrue(ranked.prefix(3).allSatisfy { $0.sourceMetadata?.brandName?.lowercased() == "fairlife" })
    }

    func testCapturedFoundationMilkRetainsItsReportedEnergy() throws {
        let milk = try XCTUnwrap(USDAFoodParser.foodItems(from: Data(foundationMilk.utf8)).first)
        XCTAssertEqual(milk.id, "usda_2257045")
        XCTAssertEqual(milk.calories, 19.3, accuracy: 0.0001)
        XCTAssertEqual(milk.servingWeight, 100)
        XCTAssertTrue(milk.sourceMetadata?.notes?.contains("general factors") == true)
    }

    func testMissingNutritionEntryDoesNotDiscardValidCapturedNeighbors() throws {
        let foods = try OpenFoodFactsParser.searchFoods(from: Data(mixedOFF.utf8))
        XCTAssertEqual(foods.count, 1)
        XCTAssertEqual(foods.first?.id, "off_0894700010137")
        XCTAssertGreaterThan(foods.first?.calories ?? 0, 0)
        XCTAssertFalse(foods.contains { $0.id == "off_1771711112786" })
    }

    func testProjectedOpenFoodFactsResponsePreservesParsedProductAndNutrition() throws {
        let full = try OpenFoodFactsParser.searchFoods(from: Data(fullOFF.utf8))
        let projected = try OpenFoodFactsParser.searchFoods(from: Data(projectedOFF.utf8))
        XCTAssertEqual(full.count, 3)
        XCTAssertEqual(full.map(\.id), projected.map(\.id))
        for (before, after) in zip(full, projected) {
            XCTAssertEqual(before.name, after.name)
            XCTAssertEqual(before.calories, after.calories)
            XCTAssertEqual(before.protein, after.protein)
            XCTAssertEqual(before.carbs, after.carbs)
            XCTAssertEqual(before.fats, after.fats)
            XCTAssertEqual(before.servingSize, after.servingSize)
            XCTAssertEqual(before.servingWeight, after.servingWeight)
            XCTAssertEqual(before.sourceMetadata?.brandName, after.sourceMetadata?.brandName)
            XCTAssertEqual(before.sourceMetadata?.barcode, after.sourceMetadata?.barcode)
            XCTAssertEqual(before.sourceMetadata?.sourceUpdatedAt, after.sourceMetadata?.sourceUpdatedAt)
            XCTAssertEqual(before.sourceMetadata?.evidenceLineage, after.sourceMetadata?.evidenceLineage)
        }
    }
